content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-28-veggie-price-005

=== 用户原始指令 (query.txt) ===
做个菜价卡片,显示一行数字话,点一下跳应用,能读天气,提醒我快不行了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做个菜价卡片,显示一行数字话,点一下跳应用,能读天气,提醒我快不行了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "view": {
      "title": {
        "type": "string",
        "description": "卡片标题，说明当前是菜价比价提醒。",
        "sampleValue": "菜价比价"
      },
      "primaryLine": {
        "type": "string",
        "description": "一行数字化菜价判断文案，适合直接作为主显示。",
        "sampleValue": "6.8元 偏高"
      },
      "caption": {
        "type": "string",
        "description": "菜价变化的简短原因或判断。",
        "sampleValue": "雨后叶菜易涨"
      },
      "warningText": {
        "type": "string",
        "description": "用户要求的强提醒短句。",
        "sampleValue": "快不行了"
      },
      "actionHint": {
        "type": "string",
        "description": "点击整卡后的短提示。",
        "sampleValue": "点一下设提醒"
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询区县名称。",
            "sampleValue": "青浦区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "小雨"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比。",
            "sampleValue": 86
          },
          "alertLevel": {
            "type": "string",
            "description": "天气预警等级或提示。",
            "sampleValue": "无预警"
          }
        },
        "updatedAt": {
          "type": "string",
          "description": "天气数据更新时间。",
          "sampleValue": "15:30"
        }
      }
    }
  },
  "assetCandidates": []
}

